source.patch:
From eb224a5545ba0e11a04dcb45b7a3abceeba3ec45 Mon Sep 17 00:00:00 2001
From: Cristy <urban-warrior@imagemagick.org>
Date: Fri, 19 Apr 2024 21:18:21 -0400
Subject: [PATCH] initialize decompression before importing profiles

---
 coders/jpeg.c | 13 +++++++------
 1 file changed, 7 insertions(+), 6 deletions(-)

diff --git a/coders/jpeg.c b/coders/jpeg.c
index 80b0726..d60b211 100644
--- a/coders/jpeg.c
+++ b/coders/jpeg.c
@@ -1378,12 +1378,6 @@ static Image *ReadOneJPEGImage(const ImageInfo *image_info,
   if (jpeg_info->arith_code == TRUE)
     (void) SetImageProperty(image,"jpeg:arithmetic-coding","true",exception);
 #endif
-  if (JPEGSetImageProfiles(client_info) == MagickFalse)
-    {
-      JPEGDestroyDecompress(jpeg_info);
-      client_info=(JPEGClientInfo *) RelinquishMagickMemory(client_info);
-      return(DestroyImageList(image));
-    }
   *offset=TellBlob(image);
   if (image_info->ping != MagickFalse)
     {
@@ -1404,8 +1398,15 @@ static Image *ReadOneJPEGImage(const ImageInfo *image_info,
       (jpeg_info->output_components != 3) && (jpeg_info->output_components != 4))
     {
       JPEGDestroyDecompress(jpeg_info);
+      client_info=(JPEGClientInfo *) RelinquishMagickMemory(client_info);
       ThrowJPEGReaderException(CorruptImageError,"ImageTypeNotSupported");
     }
+  if (JPEGSetImageProfiles(client_info) == MagickFalse)
+    {
+      JPEGDestroyDecompress(jpeg_info);
+      client_info=(JPEGClientInfo *) RelinquishMagickMemory(client_info);
+      return(DestroyImageList(image));
+    }
   memory_info=AcquireVirtualMemory((size_t) image->columns,
     (size_t) jpeg_info->output_components*sizeof(*jpeg_pixels));
   if (memory_info == (MemoryInfo *) NULL)
-- 
